import { getAnnotations } from '../stateManagement/annotation/annotationState.js';
import { utilities as cornerstoneUtilities } from '@cornerstonejs/core';
const cs3dLogger = cornerstoneUtilities.logger.toolsLog.getLogger('store.filterToolsWithAnnotationsForElement');
export default function filterToolsWithAnnotationsForElement(element, tools) {
    const result = [];
    for (let i = 0; i < tools.length; i++) {
        const tool = tools[i];
        if (!tool) {
            cs3dLogger.warn('undefined tool in filterToolsWithAnnotationsForElement');
            continue;
        }
        let annotations = getAnnotations(tool.constructor.toolName, element);
        if (!annotations?.length) {
            continue;
        }
        if (typeof tool.filterInteractableAnnotationsForElement === 'function') {
            annotations = tool.filterInteractableAnnotationsForElement(element, annotations);
        }
        if (annotations?.length > 0) {
            result.push({ tool, annotations });
        }
    }
    return result;
}
